{
  "name": "电动直线位移台",
  "name_en": "Motorized Linear Translation Stage",
  "manufacturer": "",
  "description": "这是一种通过 Arduino 与电机驱动板控制的单轴电动直线位移装置，带有限位开关，可通过 USB 串口进行回零、相对移动和绝对定位。它常用于实验室中对样品、探针、传感器或机构进行毫米级的一维位置调整。",
  "description_en": "This is a single-axis motorized linear translation device controlled by an Arduino and motor shield, with limit switches and USB serial communication for homing, relative motion, and absolute positioning. It is commonly used in laboratories for one-dimensional millimeter-scale positioning of samples, probes, sensors, or mechanical fixtures.",
  "tag_hints": [
    "motorized linear stage",
    "single-axis positioning",
    "USB serial control",
    "limit switch homing",
    "millimeter motion",
    "sample positioning"
  ],
  "actions": [
    {
      "action_name": "auto-home",
      "description": "执行回零，移动到负向限位开关基准位置。",
      "description_en": "Home the stage to the reference position at the negative limit switch."
    },
    {
      "action_name": "auto-move",
      "description": "按给定位移量进行相对移动，单位为毫米。",
      "description_en": "Move the stage by a specified relative distance in millimeters."
    },
    {
      "action_name": "auto-goto",
      "description": "移动到指定的绝对位置，单位为毫米。",
      "description_en": "Move the stage to a specified absolute position in millimeters."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与位移台控制器的连接。",
      "description_en": "Close the connection to the stage controller."
    },
    {
      "action_name": "auto-estop",
      "description": "紧急停止当前运动。",
      "description_en": "Immediately stop the current motion."
    },
    {
      "action_name": "auto-get_position",
      "description": "读取当前位置。",
      "description_en": "Read the current position."
    }
  ]
}

